.darma-loader-darma-b8-galaxy-spiral span:nth-child(8) { transform: rotate(225deg) translateX(calc(var(--loader-size, 92px) * .1)); }
.darma-loader-darma-b8-galaxy-spiral span:nth-child(9) { transform: rotate(270deg) translateX(calc(var(--loader-size, 92px) * .15)); }
